// 最顶层按照括号进行切割
vector<string> splitTopLevelItem(string& input) {
    vector<string> res;
    int depth = 0;
    int start = 0;
    int n = input.size();
    for (int i = 0; i < n; i++) {
        char c = input[i];
        if (c == '[') {
            if (depth == 0) {
                start = i;
            }
            depth += 1;
        } else if (c == ']') {
            depth -= 1;
            if (depth == 0) {
                string tmp = input.substr(start, i - start + 1);
                res.push_back(tmp);
            }
        }
        // 出现括号乱序问题 右括号大于左括号数量
        if (depth < 0) {
            flag = true;
            break;
        }
    }
​
    // 括号左右对数不匹配
    if (depth != 0) {
        flag = true;
    }
    return res;
}
