// 编码
vector<Item> encode(string& input) {
    vector<Item> res;
    if (input.empty()) {
        return res;
    }
    // 解析输入是否已[ 开头 以 ] 结尾
    if (input[0] != '[' || input.back() != ']') {
        flag = true;
        return res;
    }
​
    vector<string> ans = splitTopLevelItem(input);
    // 处理字符串过程中括号对数不匹配,异常情况
    if (flag) {
        return res;
    }
    int n = ans.size();

    for (int i = 0; i < n; i++) {
        string itemStr = ans[i];
        // 取出左右边界括号
        itemStr.pop_back();
        itemStr = itemStr.substr(1, itemStr.size()-1);
        vector<string> currentAns;
        string tmp = "";
        int m = itemStr.size();
        int j = 0;
​
        for (; j < m; j++) {
            char c = itemStr[j];
            if (c != ',') {
                tmp += c;
            } else {
                currentAns.push_back(tmp);
                tmp = "";
                if (currentAns.size() == 2) {
                    break;
                }
            }
        }
​
        string type = currentAns.back();
        // 值类型
        if (type == "Integer" || type == "String") {
            string value = itemStr.substr(j+1);
            int count = value.size();
            string typeStr = currentAns[1] == "Integer" ? "0" : "1";
            res.push_back({currentAns[0], typeStr, count, value});
        // 复合类型    
        } else if (type == "Compose") {
            // 下一层嵌套的内容
            string childrenItemStr = itemStr.substr(j+1);
            // 递归处理
            vector<Item> children =  encode(childrenItemStr);
            // 计算长度
            int m = children.size();
            // 计算长度 嵌套类型的总长度 = 各子片段的长度 + 各子长度类型字符串的长度
            int count = 0;
            string typeSrtr = "2";
            for (int i = 0; i < m; i++) {
                Item item = children[i];
                count += item.count;
                count += typeLength[item.type];
            }
            res.push_back({currentAns[0], typeSrtr, count, ""});
            res.back().children = children;
        }
    }
    return res;
}
