// 顶层根据中括号切割输入字符串，提取一级子项
function splitTopLevelItem(input) {
  const res = [];
  let depth = 0;   // 括号深度
  let start = 0;   // 当前子项起始索引
  for (let i = 0; i < input.length; i++) {
    const c = input[i];
    if (c === '[') {
      if (depth === 0) start = i;  // 深度为0时，记录开始位置
      depth++;
    } else if (c === ']') {
      depth--;
      if (depth === 0) {
        res.push(input.slice(start, i + 1)); // 取出一段完整子项
      }
    }
    if (depth < 0) {
      flag = true;  // 括号不匹配，右括号多了
      break;
    }
  }
  if (depth !== 0) flag = true;  // 括号不匹配，左括号多了
  return res;
}
​
// 对输入字符串进行编码处理，返回Item列表
function encode(input) {
  const res = [];
  if (!input) return res;
  if (input[0] !== '[' || input[input.length - 1] !== ']') {
    flag = true;   // 非法格式，必须以[]包围
    return res;
  }
  const ans = splitTopLevelItem(input);
  if (flag) return res;
​
  // 遍历所有一级子项进行解析
  for (let i = 0; i < ans.length; i++) {
    let itemStr = ans[i];
    // 去除两端括号
    itemStr = itemStr.substring(1, itemStr.length - 1);
​
    const currentAns = [];
    let tmp = '';
    let j = 0;
    // 解析前两个逗号前的内容，分别为位置和类型字符串
    while (j < itemStr.length) {
      const c = itemStr[j];
      if (c !== ',') {
        tmp += c;
      } else {
        currentAns.push(tmp);
        tmp = '';
        if (currentAns.length === 2) break;  // 找到两个逗号后停止
      }
      j++;
    }
​
    const type = currentAns[currentAns.length - 1];
    if (type === 'Integer' || type === 'String') {
      // 普通类型，后续全部为value
      const value = itemStr.substring(j + 1);
      const count = value.length;
      const typeStr = currentAns[1] === 'Integer' ? '0' : '1';
      res.push(new Item(currentAns[0], typeStr, count, value));
    } else if (type === 'Compose') {
      // 复合类型，递归编码子内容
      const childrenItemStr = itemStr.substring(j + 1);
      const children = encode(childrenItemStr);
      let count = 0;
      // 计算长度 = 所有子项长度 + 各子项类型字符串长度
      for (const item of children) {
        count += item.count + typeLength[item.type];
      }
      const composeItem = new Item(currentAns[0], '2', count, '');
      composeItem.children = children;
      res.push(composeItem);
    }
  }
  return res;
}
​
// 递归格式化输出编码结果，连续打印
function formatEncodePrint(items) {
  for (const item of items) {
    if (item.type === '0' || item.type === '1') {
      process.stdout.write(`${item.pos}#${item.type}#${item.count}#${item.value}`);
    } else {
      process.stdout.write(`${item.pos}#${item.type}#${item.count}#`);
      formatEncodePrint(item.children);
    }
  }
}
​
// 递归格式化输出解码结果，打印为符合格式的字符串
function formatDecodePrint(items) {
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (item.type === '0' || item.type === '1') {
      process.stdout.write(`[${item.pos},${typeToStringMp[item.type]},${item.value}]`);
    } else {
      process.stdout.write(`[${item.pos},${typeToStringMp[item.type]},`);
      formatDecodePrint(item.children);
      process.stdout.write(']');
    }
    if (i !== items.length - 1) process.stdout.write(',');
  }
}
