// 递归获取复合类型子内容字符串，供解码使用
function getChildrenInput(parts, index, count) {
  let pos = '';
  let type = '';
  let value = '';
  let subCount = -1;
​
  let res = '';
​
  let tmpCount = 0;
  const n = parts.length;
​
  while (index[0] < n && tmpCount < count) {
    if (pos === '') {
      pos = parts[index[0]];
    } else if (type === '') {
      type = parts[index[0]];
    } else if (subCount === -1) {
      subCount = parseInt(parts[index[0]], 10);
    } else {
      tmpCount += typeLength[type] + subCount;
​
      if (type === '0' || type === '1') {
        value = parts[index[0]];
        if (value.length < subCount) {
          flag = true;
          break;
        }
        const valuePart = value.substring(0, subCount);
        const remainngStr = value.substring(subCount);
        parts[index[0]] = remainngStr;
​
        res += pos + '#' + type + '#' + subCount + '#' + valuePart;
        index[0]--;
      } else {
        res += pos + '#' + type + '#' + subCount + '#';
        res += getChildrenInput(parts, index, subCount);
        index[0]--;
      }
      pos = '';
      type = '';
      value = '';
      subCount = -1;
    }
    index[0]++;
  }
  if (tmpCount !== count) {
    flag = true;  // 长度不匹配，解码异常
  }
  return res;
}
