package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// 类型长度映射
var typeLength = map[string]int{"0": 7, "1": 6, "2": 7}
​
// 类型字符串映射
var typeToStringMp = map[string]string{"0": "Integer", "1": "String", "2": "Compose"}
​
// 标志是否出现格式错误
var flag bool = false
​
// Item结构体定义
type Item struct {
    pos      string  // 位置
    count    int     // 长度
    typ      string  // 类型 "0", "1", "2"
    value    string  // 值
    children []Item  // 子元素
}
​
// splitTopLevelItem 按中括号层级分割顶层子项
func splitTopLevelItem(input string) []string {
    res := []string{}
    depth := 0
    start := 0
    for i, c := range input {
        if c == '[' {
            if depth == 0 {
                start = i
            }
            depth++
        } else if c == ']' {
            depth--
            if depth == 0 {
                res = append(res, input[start:i+1])
            }
        }
        // 括号乱序
        if depth < 0 {
            flag = true
            break
        }
    }
    // 左右括号数量不一致
    if depth != 0 {
        flag = true
    }
    return res
}
​
// encode 编码函数，将字符串转为Item切片
func encode(input string) []Item {
    res := []Item{}
    if input == "" {
        return res
    }
    // 判断格式
    if input[0] != '[' || input[len(input)-1] != ']' {
        flag = true
        return res
    }
​
    ans := splitTopLevelItem(input)
    if flag {
        return res
    }
​
    for _, itemStr := range ans {
        // 去除首尾中括号
        itemStr = itemStr[1 : len(itemStr)-1]
​
        currentAns := []string{}
        tmp := ""
        j := 0
        for j < len(itemStr) {
            c := itemStr[j]
            if c != ',' {
                tmp += string(c)
            } else {
                currentAns = append(currentAns, tmp)
                tmp = ""
                if len(currentAns) == 2 {
                    break
                }
            }
            j++
        }

        typ := currentAns[len(currentAns)-1]
        // 根据不同类型不同处理方式
        if typ == "Integer" || typ == "String" {
            value := itemStr[j+1:]
            count := len(value)
            typeStr := "0"
            if currentAns[1] == "String" {
                typeStr = "1"
            }
            res = append(res, Item{pos: currentAns[0], typ: typeStr, count: count, value: value})
        } else if typ == "Compose" {
            childrenItemStr := itemStr[j+1:]
            // 递归处理复合类型
            children := encode(childrenItemStr)
            // 计算复合类型长度
            count := 0
            for _, item := range children {
                count += item.count + typeLength[item.typ]
            }
            composeItem := Item{pos: currentAns[0], typ: "2", count: count, value: ""}
            composeItem.children = children
            res = append(res, composeItem)
        }
    }
    return res
}
​
// formatEncodePrint 递归格式化打印编码结果
func formatEncodePrint(items []Item) {
    for _, item := range items {
        if item.typ == "0" || item.typ == "1" {
            fmt.Printf("%s#%s#%d#%s", item.pos, item.typ, item.count, item.value)
        } else {
            fmt.Printf("%s#%s#%d#", item.pos, item.typ, item.count)
            formatEncodePrint(item.children)
        }
    }
}
​
// formatDecodePrint 递归格式化打印解码结果
func formatDecodePrint(items []Item) {
    for i, item := range items {
        if item.typ == "0" || item.typ == "1" {
            fmt.Printf("[%s,%s,%s]", item.pos, typeToStringMp[item.typ], item.value)
        } else {
            fmt.Printf("[%s,%s,", item.pos, typeToStringMp[item.typ])
            formatDecodePrint(item.children)
            fmt.Printf("]")
        }
        if i != len(items)-1 {
            fmt.Printf(",")
        }
    }
}
​
// split 按指定分隔符分割字符串
func split(str, delimiter string) []string {
    return strings.Split(str, delimiter)
}
​
// getChildrenInput 递归获取复合类型子内容字符串，供解码使用
func getChildrenInput(parts []string, index *int, count int) string {
    pos := ""
    typ := ""
    value := ""
    subCount := -1
​
    res := ""
​
    tmpCount := 0
    n := len(parts)
​
    for *index < n && tmpCount < count {
        // 按顺序赋值
        if pos == "" {
            pos = parts[*index]
        } else if typ == "" {
            typ = parts[*index]
        } else if subCount == -1 {
            var err error
            subCount, err = strconv.Atoi(parts[*index])
            if err != nil {
                flag = true
                break
            }
        } else {
            tmpCount += typeLength[typ] + subCount
            // 不同类型不同处理方式
            if typ == "0" || typ == "1" {
                value = parts[*index]
                if len(value) < subCount {
                    flag = true
                    break
                }
                valuePart := value[:subCount]
                remainingStr := value[subCount:]
                parts[*index] = remainingStr
​
                res += pos + "#" + typ + "#" + strconv.Itoa(subCount) + "#" + valuePart
                *index--
            } else {
                res += pos + "#" + typ + "#" + strconv.Itoa(subCount) + "#"

                res += getChildrenInput(parts, index, subCount)
                *index--
            }
            // 重置
            pos = ""
            typ = ""
            value = ""
            subCount = -1
        }
        *index++
    }
    if tmpCount != count {
        flag = true
    }
    return res
}
​
// decode 解码字符串为Item列表
func decode(input string) []Item {
    res := []Item{}
    parts := split(input, "#")
    m := len(parts)
    pos := ""
    typ := ""
    value := ""
    count := -1
    for i := 0; i < m; i++ {
        if pos == "" {
            pos = parts[i]
        } else if typ == "" {
            typ = parts[i]
        } else if count == -1 {
            var err error
            count, err = strconv.Atoi(parts[i])
            if err != nil {
                flag = true
                break
            }
        } else {
            if typ == "1" || typ == "0" {
                value = parts[i]
                // 两种情况:
                // 1. 最后一个数据,长度应该等于count
                // 2. 不是最后一个数组,长度应该大于count , 由 内容 + 下一个数据的位置编号
                if (i != m-1 && len(value) <= count) || (i == m-1 && len(value) != count) {
                    flag = true
                    break
                }
                remainingStr := ""
                if len(value) > count {
                    remainingStr = value[count:]
                }
                value = value[:count]
                res = append(res, Item{pos: pos, typ: typ, count: count, value: value})
                parts[i] = remainingStr
                // 因为一个元素的内容和下一个元素的id会在一起 
                i--
            } else {
                j := i
                childrenInput := getChildrenInput(parts, &j, count)
                if flag {
                    break
                }
                newItem := Item{pos: pos, typ: typ, count: count, value: ""}
                newItem.children = decode(childrenInput)
                res = append(res, newItem)
                // 因为最后一个元素的内容和下一个元素的id会在一起
                i = j - 1
            }
            pos = ""
            typ = ""
            count = -1
            value = ""
        }
    }
    // 不完整
    if pos != "" || typ != "" || count != -1 || value != "" {
        flag = true
    }
    return res
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    flag = false
​
    // 读取命令行参数（1或2）
    cmdLine, err := reader.ReadString('\n')
    if err != nil {
        fmt.Println("READ_ERROR")
        return
    }
    cmdLine = strings.TrimSpace(cmdLine)
    command, err := strconv.Atoi(cmdLine)
    if err != nil {
        fmt.Println("READ_ERROR")
        return
    }
​
    // 读取字符串输入
    inputLine, err := reader.ReadString('\n')
    if err != nil {
        fmt.Println("READ_ERROR")
        return
    }
    inputLine = strings.TrimSpace(inputLine)
​
    if command == 1 {
        items := encode(inputLine)
        if flag {
            fmt.Println("ENCODE_ERROR")
        } else {
            formatEncodePrint(items)
            fmt.Println()
        }
    } else if command == 2 {
        items := decode(inputLine)
        if flag {
            fmt.Println("DECODE_ERROR")
        } else {
            formatDecodePrint(items)
            fmt.Println()
        }
    } 
}
